require_once __DIR__.'/auth.php';require_once __DIR__.'/employee_admin.php';require_once __DIR__.'/task_workflow.php';
$isAdmin=($taskWorkspaceRole??'employee')==='admin';$isAdmin?require_admin():require_login_any_role(['employee']);$actor=current_user()??[];$svc=new TaskWorkflowService(get_db(),$actor);$ok=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{require_valid_csrf();$a=(string)($_POST['task_action']??'');$id=(int)($_POST['task_id']??0);$v=(int)($_POST['version']??0);if($a==='create'){$initial=[];$f=$_FILES['attachments']??[];foreach((array)($f['name']??[]) as $i=>$name)if($name!=='')$initial[]=['name'=>$name,'tmp_name'=>$f['tmp_name'][$i]??'','error'=>$f['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$f['size'][$i]??0];$svc->create($_POST,$initial);$ok='Official task assigned.';}elseif($a==='post'){$svc->post($id,$v,(string)($_POST['message_type']??'reply'),trim((string)($_POST['body']??'')));$ok='Message posted.';}elseif($a==='upload'){$svc->upload($id,$v,$_FILES['attachment']??[]);$ok='Proof uploaded.';}elseif($a==='reassign'){$svc->reassign($id,$v,(int)($_POST['assignee_id']??0));$ok='Task reassigned.';}elseif($a==='revise'){$svc->revise($id,$v,($_POST['due_date']??'')?:null,($_POST['due_time']??'')?:null,(string)($_POST['priority']??'medium'));$ok='Schedule updated.';}elseif($a==='archive'){$svc->archive($id,$v,!empty($_POST['archive']));$ok='Archive updated.';}elseif($a==='reminder_create'&&!$isAdmin){$title=trim((string)($_POST['title']??''));if($title==='')throw new TaskWorkflowException('Reminder title is required.');$q=get_db()->prepare('INSERT INTO personal_reminders(employee_id,title,due_at,created_at) VALUES(?,?,?,?)');$q->execute([(int)$actor['id'],$title,($_POST['due_at']??'')?:null,(new DateTimeImmutable('now',new DateTimeZone('Asia/Kolkata')))->format('Y-m-d H:i:s')]);$ok='Personal reminder created.';}elseif($a==='reminder_complete'&&!$isAdmin){$q=get_db()->prepare('UPDATE personal_reminders SET completed_at=? WHERE id=? AND employee_id=? AND completed_at IS NULL');$q->execute([(new DateTimeImmutable('now',new DateTimeZone('Asia/Kolkata')))->format('Y-m-d H:i:s'),$id,(int)$actor['id']]);$ok='Personal reminder completed.';}else{$svc->transition($id,$v,$a,trim((string)($_POST['body']??'')));$ok='Workflow updated.';}}catch(Throwable $e){$error=$e->getMessage();}}
function te(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$db=get_db();$where=$isAdmin?'1=1':'t.assignee_id=:uid';$p=$isAdmin?[]:[':uid'=>(int)$actor['id']];$today=(new DateTimeImmutable('today',new DateTimeZone('Asia/Kolkata')))->format('Y-m-d');foreach(['status'=>'workflow_status','next_action'=>'responsibility','priority'=>'workflow_priority','employee'=>'assignee_id'] as $q=>$col)if(!empty($_GET[$q])&&$_GET[$q]!=='all'){$where.=" AND t.$col=:$q";$p[":$q"]=$_GET[$q];}if(($_GET['due']??'')==='overdue'){$where.=" AND t.due_date<:business_due AND t.workflow_status NOT IN ('completed','cancelled')";$p[':business_due']=$today;}elseif(($_GET['due']??'')==='today'){$where.=' AND t.due_date=:business_due';$p[':business_due']=$today;}elseif(($_GET['due']??'')==='upcoming'){$where.=' AND t.due_date>:business_due';$p[':business_due']=$today;}elseif(($_GET['due']??'')==='none'){$where.=' AND t.due_date IS NULL';}if(isset($_GET['task'])&&ctype_digit((string)$_GET['task'])){$where.=' AND t.id=:deep_task';$p[':deep_task']=(int)$_GET['task'];}$view=(string)($_GET['view']??'active');$where.=match($view){'completed'=>" AND t.workflow_status='completed' AND t.archived_flag=0",'cancelled'=>" AND t.workflow_status='cancelled' AND t.archived_flag=0",'archived'=>' AND t.archived_flag=1',default=>" AND t.workflow_status NOT IN ('completed','cancelled') AND t.archived_flag=0"};if(trim((string)($_GET['category']??''))!==''){$where.=' AND (t.category LIKE :category OR t.linked_entity_type LIKE :category OR t.linked_entity_id LIKE :category)';$p[':category']='%'.trim((string)$_GET['category']).'%';}if(trim((string)($_GET['search']??''))!==''){$where.=' AND (t.title LIKE :search OR t.description LIKE :search OR t.category LIKE :search OR t.linked_entity_id LIKE :search)';$p[':search']='%'.trim((string)$_GET['search']).'%';}$s=$db->prepare("SELECT t.*,u.full_name assignee_name,o.occurrence_number FROM portal_tasks t LEFT JOIN users u ON u.id=t.assignee_id LEFT JOIN task_occurrences o ON o.task_id=t.id WHERE $where ORDER BY CASE t.responsibility WHEN 'admin' THEN 0 WHEN 'employee' THEN 1 ELSE 2 END,CASE t.workflow_priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 ELSE 2 END,CASE WHEN t.due_date<:today THEN 0 WHEN t.due_date=:today THEN 1 ELSE 2 END,t.last_activity_at DESC");$p[':today']=$today;$s->execute($p);$tasks=$s->fetchAll();$employees=(new CanonicalEmployeeRepository($db))->active();$allOfficial=$db->prepare('SELECT workflow_status,due_date,completed_at,responsibility FROM portal_tasks WHERE official_flag=1'.($isAdmin?'':' AND assignee_id=?'));$allOfficial->execute($isAdmin?[]:[(int)$actor['id']]);$summary=['overdue'=>0,'today'=>0,'week'=>0,'admin'=>0,'review'=>0,'blocked'=>0,'unacknowledged'=>0,'new'=>0,'mine'=>0,'progress'=>0,'waiting'=>0,'correction'=>0,'approved'=>0];$week=(new DateTimeImmutable('today',new DateTimeZone('Asia/Kolkata')))->modify('monday this week')->format('Y-m-d');foreach($allOfficial->fetchAll() as $x){if(!in_array($x['workflow_status'],['completed','cancelled'],true)&&$x['due_date']&&$x['due_date']<$today)$summary['overdue']++;if(!in_array($x['workflow_status'],['completed','cancelled'],true)&&$x['due_date']===$today)$summary['today']++;if($x['completed_at']&&substr($x['completed_at'],0,10)>=$week)$summary['week']++;if($x['responsibility']==='admin')$summary['admin']++;if($x['workflow_status']==='submitted')$summary['review']++;if($x['workflow_status']==='blocked')$summary['blocked']++;if($x['workflow_status']==='assigned'){$summary['unacknowledged']++;$summary['new']++;}if($x['responsibility']==='employee')$summary['mine']++;if($x['workflow_status']==='in_progress')$summary['progress']++;if($x['responsibility']==='admin'&&!in_array($x['workflow_status'],['completed','cancelled'],true))$summary['waiting']++;if($x['workflow_status']==='correction_required')$summary['correction']++;if($x['workflow_status']==='completed')$summary['approved']++;}$reminders=[];if(!$isAdmin){$q=$db->prepare('SELECT * FROM personal_reminders WHERE employee_id=? ORDER BY completed_at IS NOT NULL,due_at,id');$q->execute([(int)$actor['id']]);$reminders=$q->fetchAll();}
