<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=te(csrf_token())?>"><title><?=$isAdmin?'Task Operations':'My Work'?></title><style>body{margin:0;background:#f3f6fb;color:#172033;font:15px system-ui}.wrap{max-width:1180px;margin:auto;padding:18px}.panel,.card{background:#fff;border:1px solid #dbe3ef;border-radius:16px;padding:16px;margin-bottom:14px}.grid,.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.cards{grid-template-columns:repeat(auto-fit,minmax(320px,1fr))}input,select,textarea,button{font:inherit;padding:10px;border:1px solid #b8c4d6;border-radius:9px;box-sizing:border-box;width:100%}textarea{min-height:75px}button{background:#174ea6;color:#fff;font-weight:700;min-height:42px}.task{border-left:5px solid #5271ff}.meta,.actions{display:flex;gap:7px;flex-wrap:wrap}.pill{padding:4px 8px;background:#eef3fb;border-radius:99px;font-size:12px}.actions form{display:flex;gap:5px;flex:1;min-width:210px}.timeline{border-left:2px solid #ccd7e8;margin:12px 5px;padding-left:12px}.entry{margin:10px 0;overflow-wrap:anywhere}.alert{padding:12px;border-radius:9px}.error{background:#fee2e2}.success{background:#dcfce7}@media(max-width:540px){.wrap{padding:9px}.cards{display:block}.task{margin-bottom:12px}.actions form{min-width:100%}}</style></head><body><main class="wrap"><header class="panel"><div class="meta"><?php require __DIR__.'/notification_bell.php';?></div><a href="<?=$isAdmin?'admin-dashboard.php':'employee-dashboard.php'?>">← Dashboard</a><h1><?=$isAdmin?'Task Operations':'My Work'?></h1><p><?=$isAdmin?'Official assignments and accountable review.':'Official assigned work; personal reminders are counted separately.'?></p></header><?php if($ok):?><p class="alert success"><?=te($ok)?></p><?php endif;if($error):?><p class="alert error"><?=te($error)?></p><?php endif?>
<section class="grid summary-cards"><?php if($isAdmin):?><a class="card" href="?view=active&next_action=admin"><b>Needs admin action</b><strong><?=$summary['admin']?></strong></a><a class="card" href="?view=active&status=submitted"><b>Awaiting review</b><strong><?=$summary['review']?></strong></a><a class="card" href="?view=active&status=blocked"><b>Blocked</b><strong><?=$summary['blocked']?></strong></a><a class="card" href="?view=active&status=assigned"><b>Not acknowledged</b><strong><?=$summary['unacknowledged']?></strong></a><a class="card" href="?view=active&due=overdue"><b>Overdue</b><strong><?=$summary['overdue']?></strong></a><a class="card" href="?view=active&due=today"><b>Due today</b><strong><?=$summary['today']?></strong></a><a class="card" href="?view=completed"><b>Completed this week</b><strong><?=$summary['week']?></strong></a><?php else:?><a class="card" href="?view=active&status=assigned"><b>New assignments</b><strong><?=$summary['new']?></strong></a><a class="card" href="?view=active&next_action=employee"><b>Needs my action</b><strong><?=$summary['mine']?></strong></a><a class="card" href="?view=active&status=in_progress"><b>In progress</b><strong><?=$summary['progress']?></strong></a><a class="card" href="?view=active&due=overdue"><b>Overdue</b><strong><?=$summary['overdue']?></strong></a><a class="card" href="?view=active&next_action=admin"><b>Waiting for admin</b><strong><?=$summary['waiting']?></strong></a><a class="card" href="?view=active&status=correction_required"><b>Correction required</b><strong><?=$summary['correction']?></strong></a><a class="card" href="?view=completed"><b>Approved complete</b><strong><?=$summary['approved']?></strong></a><?php endif?></section><?php if($isAdmin):?><details class="panel"><summary><b>Assign official work</b></summary><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="task_action" value="create"><div class="grid"><label>Title<input required name="title"></label><label>Employee<select required name="assignee_id"><option value="">Select</option><?php foreach($employees as $e):?><option value="<?=te($e['id'])?>"><?=te($e['name'])?></option><?php endforeach?></select></label><label>Priority<select name="priority"><?php foreach(['low','medium','high','urgent'] as $x):?><option><?=$x?></option><?php endforeach?></select></label><label>Category<input name="category"></label><label>Start<input type="date" name="start_date"></label><label>Due<input type="date" name="due_date"></label><label>Time<input type="time" name="due_time"></label><label>Recurrence<select id="frequency_type" name="frequency_type" aria-controls="custom-recurrence"><?php foreach(['once','daily','weekly','monthly','custom'] as $x):?><option><?=$x?></option><?php endforeach?></select></label><div id="custom-recurrence"><label>Every N days<input type="number" min="1" name="custom_every_n_days"></label></div><label>Reference type<select name="linked_entity_type"><option value="">None</option><option>customer</option><option>project</option><option>site</option></select></label><label>Reference ID<input name="linked_entity_id"></label><label>Initial attachments<input type="file" name="attachments[]" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt"></label></div><label>Detailed instructions<textarea required name="description"></textarea></label><label>Expected outcome<textarea required name="expected_outcome"></textarea></label><label><input style="width:auto" type="checkbox" name="proof_required" value="1"> Require proof</label><button>Assign</button></form></details><?php endif?>
<form class="panel grid" method="get"><label>Search<input name="search" value="<?=te($_GET['search']??'')?>"></label><label>View<select name="view"><?php foreach(['active','completed','cancelled','archived'] as $x):?><option <?=$view===$x?'selected':''?>><?=$x?></option><?php endforeach?></select></label><label>Status<select name="status"><option>all</option><?php foreach(TaskWorkflowService::STATES as $x):?><option value="<?=$x?>" <?=($_GET['status']??'all')===$x?'selected':''?>><?=te(str_replace('_',' ',$x))?></option><?php endforeach?></select></label><label>Next action<select name="next_action"><option>all</option><?php foreach(['admin','employee','none'] as $x):?><option <?=$x===($_GET['next_action']??'')?'selected':''?>><?=$x?></option><?php endforeach?></select></label><label>Priority<select name="priority"><option>all</option><option value="urgent" <?=($_GET['priority']??'')==='urgent'?'selected':''?>>urgent</option><option value="high" <?=($_GET['priority']??'')==='high'?'selected':''?>>high</option><option value="medium" <?=($_GET['priority']??'')==='medium'?'selected':''?>>medium</option><option value="low" <?=($_GET['priority']??'')==='low'?'selected':''?>>low</option></select></label><?php if($isAdmin):?><label>Employee<select name="employee"><option>all</option><?php foreach($employees as $e):?><option value="<?=te($e['id'])?>" <?=((string)($_GET['employee']??'')===(string)$e['id'])?'selected':''?>><?=te($e['name'])?></option><?php endforeach?></select></label><?php endif?><label>Due<select name="due"><option value="">all</option><?php foreach(['overdue','today','upcoming','none'] as $x):?><option value="<?=$x?>" <?=($_GET['due']??'')===$x?'selected':''?>><?=$x==='none'?'no due date':$x?></option><?php endforeach?></select></label><label>Category/reference<input name="category" value="<?=te($_GET['category']??'')?>"></label><button>Filter</button></form>
<section class="cards"><?php foreach($tasks as $t):$d=$svc->detail((int)$t['id']);?><article class="card task" id="task-<?=$t['id']?>"><h2><?=te($t['title'])?></h2><div class="meta"><span class="pill"><?=te(str_replace('_',' ',$t['workflow_status']))?></span><span class="pill"><?=$t['responsibility']==='none'?'No action required':'Next action: '.ucfirst($t['responsibility'])?></span><span class="pill"><?=te($t['workflow_priority'])?></span><span class="pill">Occurrence <?=te($t['occurrence_number']??1)?></span></div><p><b>Assigned:</b> <?=te($t['assignee_name'])?><br><b>Due:</b> <?=te(trim((string)$t['due_date'].' '.(string)$t['due_time']))?><br><b>Category/reference:</b> <?=te(trim((string)$t['category'].' '.(string)$t['linked_entity_type'].' '.(string)$t['linked_entity_id']))?></p><p><b>Instructions</b><br><?=nl2br(te($t['description']))?></p><p><b>Expected outcome</b><br><?=nl2br(te($t['expected_outcome']))?></p><?php if($t['submission_summary']):?><p><b>Submission:</b> <?=nl2br(te($t['submission_summary']))?></p><?php endif?><details><summary>Chronological timeline</summary><div class="timeline"><?php foreach($d['timeline'] as $x):?><div class="entry"><b><?=te($x['label'])?> · <?=te($x['actor_name'])?></b> <small><?=te($x['created_at'])?></small><?php if(isset($x['body'])):?><br><?=nl2br(te($x['body']))?><?php endif;if(isset($x['attachment'])):?><br><a href="task-attachment.php?id=<?=$x['id']?>"><?=te($x['attachment']['original_name'])?></a><?php endif?></div><?php endforeach?></div></details>
<div class="actions"><?php foreach($d['allowed_actions'] as $a):?><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="<?=$a?>"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><?php if(in_array($a,['blocker_respond','blocker_resolve','correction','reopen','cancel','block','submit'])):?><input name="body" placeholder="Details<?=in_array($a,['correction','reopen','cancel','block','submit'])?' required':''?>"><?php endif?><button><?=te(['acknowledge'=>'Acknowledge','start'=>'Start work','block'=>'Report blocker','blocker_respond'=>'Keep blocked · Send response','blocker_resolve'=>'Resolve & resume','submit'=>'Submit for review','correction'=>'Request correction','correction_resume'=>'Acknowledge correction & resume','approve'=>'Approve completion','reopen'=>'Reopen task','cancel'=>'Cancel task'][$a]??ucwords(str_replace('_',' ',$a)))?></button></form><?php endforeach?></div><?php if(!in_array($t['workflow_status'],['completed','cancelled'])):?><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="post"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><select name="message_type"><option>reply</option><option>progress</option></select><input required name="body" placeholder="Message"><button>Post</button></form><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="task_action" value="upload"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><input required type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt"><button>Upload proof</button></form></div><?php endif?><?php if($isAdmin&&!in_array($t['workflow_status'],['completed','cancelled'],true)&&!(int)$t['archived_flag']):?><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="reassign"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><select name="assignee_id"><?php foreach($employees as $e):?><option value="<?=te($e['id'])?>"><?=te($e['name'])?></option><?php endforeach?></select><button>Reassign</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="revise"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><input type="date" name="due_date" value="<?=te($t['due_date'])?>"><input type="time" name="due_time" value="<?=te($t['due_time'])?>"><select name="priority"><?php foreach(['low','medium','high','urgent'] as $x):?><option <?=$x===$t['workflow_priority']?'selected':''?>><?=$x?></option><?php endforeach?></select><button>Revise due date & priority</button></form><?php if(in_array($t['workflow_status'],['completed','cancelled'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="archive"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><input type="hidden" name="archive" value="<?=$t['archived_flag']?0:1?>"><button><?=$t['archived_flag']?'Unarchive':'Archive'?></button></form><?php endif?></div><?php endif?><?php if($isAdmin&&in_array($t['workflow_status'],['completed','cancelled'],true)):?><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="archive"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><input type="hidden" name="archive" value="<?=$t['archived_flag']?0:1?>"><button><?=$t['archived_flag']?'Unarchive':'Archive'?></button></form></div><?php endif?></article><?php endforeach?></section><?php if(!$isAdmin):?><section class="panel"><h2>My Reminders</h2><p>Personal reminders are private and excluded from official task metrics and notifications.</p><form method="post" class="grid"><?=csrf_field()?><input type="hidden" name="task_action" value="reminder_create"><label>Reminder<input required name="title"></label><label>When<input type="datetime-local" name="due_at"></label><button>Create reminder</button></form><?php foreach($reminders as $r):?><div class="entry"><b><?=te($r['title'])?></b> <?=te($r['due_at'])?> <?php if($r['completed_at']):?>✓ completed<?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="reminder_complete"><input type="hidden" name="task_id" value="<?=$r['id']?>"><button>Complete reminder</button></form><?php endif?></div><?php endforeach?></section><?php endif?></main><script>document.addEventListener('DOMContentLoaded',function(){var s=document.getElementById('frequency_type'),c=document.getElementById('custom-recurrence');if(!s||!c)return;function sync(){var show=s.value==='custom';c.hidden=!show;c.querySelector('input').required=show;}s.addEventListener('change',sync);sync();});</script></body></html>
